# CTC 貪婪解碼器與序列對齊模擬
import numpy as np

def ctc_greedy_decoder(emissions, vocabulary, blank_idx=0):
    best_path = np.argmax(emissions, axis=1)
    decoded_indices = []
    prev_idx = -1
    for idx in best_path:
        if idx == prev_idx:
            continue
        prev_idx = idx
        if idx != blank_idx:
            decoded_indices.append(idx)
    final_chars = [vocabulary[i] for i in decoded_indices]
    return "".join(final_chars)
